update public.question_bank set question = $q${"form":"bai_tap","type":"multiple_choice","topic":"Công của lực và trường hợp lực xiên góc","answer":3,"options":["là đại lượng vô hướng.","có giá trị đại số.","được tính bằng biểu thức$F_{ms}.s.cosa$.","luôn luôn dương."],"question":"<p class=\"text-base leading-relaxed my-2\">Chọn câu <strong>sai</strong>. Công của lực</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực là đại lượng vô hướng, có giá trị đại số: công có thể dương, âm hoặc bằng không tùy theo góc giữa lực và độ dời.</p><p class=\"text-base leading-relaxed my-2\">Công của lực không đổi tác dụng lên vật có độ dời $\\vec{s}$ được tính theo công thức:</p><p class=\"text-base leading-relaxed my-2\">$A = F.s.\\cos\\alpha$</p><p class=\"text-base leading-relaxed my-2\">Trong đó $\\alpha$ là góc giữa vectơ lực $\\vec{F}$ và vectơ độ dời $\\vec{s}$.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">- A đúng: công là đại lượng vô hướng.</p><p class=\"text-base leading-relaxed my-2\">- B đúng: công có giá trị đại số.</p><p class=\"text-base leading-relaxed my-2\">- C đúng: $A = F.s.\\cos\\alpha$ (với $F$ là lực tác dụng).</p><p class=\"text-base leading-relaxed my-2\">- D sai: vì $\\cos\\alpha$ có thể âm (khi $90^\\circ \\lt  \\alpha \\le 180^\\circ$), khi đó công âm. Ví dụ lực ma sát thường sinh công âm.</p><p class=\"text-base leading-relaxed my-2\">Vậy câu sai là D.</p>","difficultySource":"ai"}$q$::jsonb, content_hash = public.question_content_hash($q${"form":"bai_tap","type":"multiple_choice","topic":"Công của lực và trường hợp lực xiên góc","answer":3,"options":["là đại lượng vô hướng.","có giá trị đại số.","được tính bằng biểu thức$F_{ms}.s.cosa$.","luôn luôn dương."],"question":"<p class=\"text-base leading-relaxed my-2\">Chọn câu <strong>sai</strong>. Công của lực</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực là đại lượng vô hướng, có giá trị đại số: công có thể dương, âm hoặc bằng không tùy theo góc giữa lực và độ dời.</p><p class=\"text-base leading-relaxed my-2\">Công của lực không đổi tác dụng lên vật có độ dời $\\vec{s}$ được tính theo công thức:</p><p class=\"text-base leading-relaxed my-2\">$A = F.s.\\cos\\alpha$</p><p class=\"text-base leading-relaxed my-2\">Trong đó $\\alpha$ là góc giữa vectơ lực $\\vec{F}$ và vectơ độ dời $\\vec{s}$.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">- A đúng: công là đại lượng vô hướng.</p><p class=\"text-base leading-relaxed my-2\">- B đúng: công có giá trị đại số.</p><p class=\"text-base leading-relaxed my-2\">- C đúng: $A = F.s.\\cos\\alpha$ (với $F$ là lực tác dụng).</p><p class=\"text-base leading-relaxed my-2\">- D sai: vì $\\cos\\alpha$ có thể âm (khi $90^\\circ \\lt  \\alpha \\le 180^\\circ$), khi đó công âm. Ví dụ lực ma sát thường sinh công âm.</p><p class=\"text-base leading-relaxed my-2\">Vậy câu sai là D.</p>","difficultySource":"ai"}$q$::jsonb), updated_at = now() where id = 1544606 and note = 'nap-vl10-c4-20261020';
update public.question_bank set question = $q${"form":"bai_tap","type":"multiple_choice","topic":"Thế năng trọng trường và mốc thế năng","answer":0,"options":["Công của trọng lực bằng hiệu thế năng tại vị trí đầu và tại vị trí cuối.","Trọng lực sinh công âm khi vật đi từ cao xuống thấp.","Trọng lực sinh công dương khi đưa vật từ thấp lên cao.","Công của trọng lực đi theo đường thẳng nối hai điểm đầu và cuối bao giờ cũng nhỏ hơn đi theo đường gấp khúc giữa hai điểm đó."],"question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là <strong>đúng</strong> khi nói về thế năng trọng trường?</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Thế năng trọng trường: $W_t = mgz$. Công của trọng lực không phụ thuộc dạng đường đi, chỉ phụ thuộc vị trí đầu và cuối.</p><p class=\"text-base leading-relaxed my-2\">Với trọng lực, công thức: $A_{P} = mg(z_1 - z_2) = W_{t1} - W_{t2}$, tức là công của trọng lực bằng hiệu thế năng ở vị trí đầu và vị trí cuối.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Đúng, khớp với công thức trên.</p><p class=\"text-base leading-relaxed my-2\">B. Sai. Khi vật đi từ cao xuống thấp thì $z_1 \\gt  z_2$, nên $A_P = mg(z_1 - z_2) \\gt  0$: trọng lực sinh công dương.</p><p class=\"text-base leading-relaxed my-2\">C. Sai. Khi đưa vật từ thấp lên cao thì $z_1 \\lt  z_2$, nên $A_P \\lt  0$: trọng lực sinh công âm.</p><p class=\"text-base leading-relaxed my-2\">D. Sai. Công của trọng lực không phụ thuộc đường đi; đi theo đường thẳng hay đường gấp khúc giữa hai điểm đều cho cùng một giá trị.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là A.</p>","difficultySource":"ai"}$q$::jsonb, content_hash = public.question_content_hash($q${"form":"bai_tap","type":"multiple_choice","topic":"Thế năng trọng trường và mốc thế năng","answer":0,"options":["Công của trọng lực bằng hiệu thế năng tại vị trí đầu và tại vị trí cuối.","Trọng lực sinh công âm khi vật đi từ cao xuống thấp.","Trọng lực sinh công dương khi đưa vật từ thấp lên cao.","Công của trọng lực đi theo đường thẳng nối hai điểm đầu và cuối bao giờ cũng nhỏ hơn đi theo đường gấp khúc giữa hai điểm đó."],"question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là <strong>đúng</strong> khi nói về thế năng trọng trường?</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Thế năng trọng trường: $W_t = mgz$. Công của trọng lực không phụ thuộc dạng đường đi, chỉ phụ thuộc vị trí đầu và cuối.</p><p class=\"text-base leading-relaxed my-2\">Với trọng lực, công thức: $A_{P} = mg(z_1 - z_2) = W_{t1} - W_{t2}$, tức là công của trọng lực bằng hiệu thế năng ở vị trí đầu và vị trí cuối.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Đúng, khớp với công thức trên.</p><p class=\"text-base leading-relaxed my-2\">B. Sai. Khi vật đi từ cao xuống thấp thì $z_1 \\gt  z_2$, nên $A_P = mg(z_1 - z_2) \\gt  0$: trọng lực sinh công dương.</p><p class=\"text-base leading-relaxed my-2\">C. Sai. Khi đưa vật từ thấp lên cao thì $z_1 \\lt  z_2$, nên $A_P \\lt  0$: trọng lực sinh công âm.</p><p class=\"text-base leading-relaxed my-2\">D. Sai. Công của trọng lực không phụ thuộc đường đi; đi theo đường thẳng hay đường gấp khúc giữa hai điểm đều cho cùng một giá trị.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là A.</p>","difficultySource":"ai"}$q$::jsonb), updated_at = now() where id = 1544715 and note = 'nap-vl10-c4-20261020';
